<script setup lang="ts">import{ref,computed}from'vue';import type{OptionAnalysis}from'../../core/models';const props=defineProps<{options:OptionAnalysis[]}>();const hidden=ref(new Set<string>());const colors=['#4f5db7','#d58a32','#8b5f88','#3b8667'];const x=(i:number)=>70+i*180;const y=(score:number)=>230-score*1.75;const path=(o:OptionAnalysis)=>o.points.map((p,i)=>`${i?'L':'M'} ${x(i)} ${y(p.score)}`).join(' ');function toggle(id:string){const next=new Set(hidden.value);next.has(id)?next.delete(id):next.add(id);hidden.value=next}const visible=computed(()=>props.options.filter(o=>!hidden.value.has(o.option.id)))</script>
<template><div class="curve-card"><div class="curve-head"><div><span>REGRET OVER TIME</span><h3>后悔曲线</h3></div><div class="legend"><button v-for="(o,i) in options" :key="o.option.id" :class="{off:hidden.has(o.option.id)}" @click="toggle(o.option.id)"><i :style="{background:colors[i]}"></i>{{o.option.name}}</button></div></div><svg viewBox="0 0 500 280" role="img" aria-label="各选项未来十年的后悔指数曲线"><g class="grid"><line v-for="v in [0,25,50,75,100]" :key="v" x1="55" x2="460" :y1="y(v)" :y2="y(v)"/><text v-for="v in [0,25,50,75,100]" :key="`t${v}`" x="22" :y="y(v)+4">{{v}}</text></g><g v-for="o in visible" :key="o.option.id"><path :d="path(o)" fill="none" :stroke="colors[options.indexOf(o)]" stroke-width="4"/><circle v-for="(p,i) in o.points" :key="p.horizon" :cx="x(i)" :cy="y(p.score)" r="6" :fill="colors[options.indexOf(o)]"><title>{{o.option.name}} · {{p.horizon}}年：{{p.score}}</title></circle></g><text v-for="(h,i) in [1,5,10]" :key="h" :x="x(i)" y="268" text-anchor="middle">{{h}} 年后</text></svg></div></template>
